749	            }
750	            const float rho_over_norm = *ron_bc;
751	            // (b) Backup + perturb p in place: p' = p + rho_over_norm·g. Grid-strided
752	            //     over the flat param vector (each element owned once → no race).
753	            {
754	                const int64_t gstride = (int64_t)blockDim.x * gridDim.x;
755	                for (int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
756	                     i < total_e; i += gstride) {
757	                    sam_backup[i] = params[i];
758	                    params[i] = params[i] + rho_over_norm * grad[i];
759	                }
760	            }
761	            bar.sync();   // B2.4c: all params perturbed before the 2nd forward reads them
762	            // (c) SECOND fwd+bwd at the perturbed weights → g_sam in `sam_grad`. Same
763	            //     scalar batch-parallel P1+P2 as the first pass, but: re-zero the
764	            //     per-CTA full-grad partial, do NOT write the loss, reduce into
765	            //     `sam_grad` (NOT `grad`). `w`/`g` already wrap params(perturbed)/my_part.
766	            for (int64_t i = threadIdx.x; i < total_p; i += blockDim.x) my_part[i] = 0.0f;
767	            bar.sync();   // B2.4d: partials cleared before the 2nd backward accumulates
768	            {
769	                const int base = B / nCTA, rem = B % nCTA;
770	                const int b0 = cta * base + (cta < rem ? cta : rem);
771	                const int cnt = base + (cta < rem ? 1 : 0);
772	                const int b1 = b0 + cnt;
773	                __shared__ int tok_s2[mb::kSeq];
774	                __shared__ int tgt_s2;
775	                for (int b = b0; b < b1; ++b) {
776	                    if (threadIdx.x < mb::kSeq) tok_s2[threadIdx.x] = tok.tokens[(int64_t)b * mb::kSeq + threadIdx.x];
777	                    if (threadIdx.x == 0) tgt_s2 = tok.targets[b];
778	                    __syncthreads();
779	                    (void)mb_forward_sample(w, tok_s2, tgt_s2, &sm);
780	                    mb_backward_sample(w, g, tok_s2, tgt_s2, B, &sm);
781	                    __syncthreads();
782	                }
783	            }
784	            bar.sync();   // B2.4e: all 2nd-pass full-grad partials complete
785	            {
786	                __shared__ int task_slot_s;
787	                TaskQueue qs = ctx.queue();
788	                for (int t = qs.next_block(&task_slot_s); t < kMambaNumTensors;
789	                     t = qs.next_block(&task_slot_s)) {
790	                    const int n = kMambaSizes[t];
791	                    const int64_t off = (int64_t)kMambaOffsets[t];
792	                    for (int i = threadIdx.x; i < n; i += blockDim.x) {
793	                        float acc = 0.0f;
794	                        for (int c = 0; c < nCTA; ++c) acc += part_base[(int64_t)c * total_p + off + i];
795	                        sam_grad[off + i] = acc;
796	                    }
797	                }
798	            }
799	            bar.sync();   // B2.4f: g_sam fully assembled in sam_grad
800	            // (d) WRITE the SAM side-channel (into the persistent state slice) + restore p.
801	            //     LookSAM → sam_dir = g_sam − g; SuperGrok11/15/SuperGrok2 → sharpness =
802	            //     (g_sam − g)² (SG2 shares the SAM 2nd-backward machinery: its meta-net's
803	            //     2nd MLP input is the SAME sharpness signal, read by sg2_meta_stages).
804	            //     Mirrors the decoder/vit twins' unified P2.4 write.
805	            {
806	                const int64_t gstride = (int64_t)blockDim.x * gridDim.x;
807	                for (int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
808	                     i < total_e; i += gstride) {
809	                    const float diff = sam_grad[i] - grad[i];
810	                    if constexpr (Opt == OptId::LookSAM) {
811	                        // st.sam_dir is the extra-slice base (host-bound). g_sam − g.
812	                        const_cast<float*>(st.sam_dir)[i] = diff;
813	                    } else {
814	                        // SuperGrok11/15/SuperGrok2: sharpness = (g_sam − g)² (state slice).
815	                        const_cast<float*>(st.sharpness)[i] = diff * diff;
816	                    }
817	                    params[i] = sam_backup[i];   // restore the ORIGINAL weights
818	                }
819	            }
820	            bar.sync_reset(ctx.g_next_task);   // B2.4g: params restored + sam_dir ready; reset queue for P3
821	        }
822	    }
