824	    // ── P2.5 (GrokAdamW ONLY): GLOBAL grad-norm clip coefficient. PORT of the
825	    //    decoder/vit TC kernels' P2.5 (fused_decoder_megakernel.cuh:461-512) — the
826	    //    eager grokadamw clips the WHOLE grad set to grad_clip via a GLOBAL L2 norm
827	    //    (clip_grad_norms_device_side → total_norm = sqrt(Σ_i ‖g_i‖²), clip_coef =
828	    //    grad_clip/(total_norm+1e-6) when total_norm>grad_clip, else 1) BEFORE the
829	    //    apply. Replicated on the REDUCED grad with a deterministic ascending
830	    //    reduction (NO float atomic — COMPONENT_CONTRACT): each CTA sums a contiguous
831	    //    element-range into a per-CTA partial slot, CTA0 sums the partials in
832	    //    ASCENDING CTA order → total_norm → clip_coef, broadcast via a workspace slot.
833	    //    grad is NOT mutated (the return_grad oracle + the eager-side clip both see
834	    //    the unclipped reduced grad); the coefficient is applied per-element inside
835	    //    apply_optimizer<GrokAdamW>. Guarded so every other opt's P3 is byte-identical
836	    //    (no extra barrier/work). loss_part (nCTA) + loss_out (1) are free scratch
837	    //    here: the reduced loss is already in *tok.loss_out (a separate pointer).
838	    //    EXTENDED to NeuralGrok (same eager global clip; consumed in apply_optimizer<NeuralGrok>).
839	    if constexpr (Opt == OptId::GrokAdamW || Opt == OptId::NeuralGrok) {
840	        float* sq_part = loss_part;          // [nCTA] per-CTA Σ g²  (ascending reduce)
841	        float* coef_bc = loss_out;           // [1] broadcast clip_coef
842	        const int64_t total = kMambaTotalElems;
843	        const int64_t base = total / nCTA, rem = total % nCTA;
844	        const int64_t e0 = (int64_t)cta * base + (cta < rem ? cta : rem);
845	        const int64_t ecnt = base + (cta < rem ? 1 : 0);
846	        float tsum = 0.0f;
847	        for (int64_t i = threadIdx.x; i < ecnt; i += blockDim.x) {
848	            const float gv = grad[e0 + i];
849	            tsum += gv * gv;
850	        }
851	        // Block reduction via a 256-wide MambaSampleSmem field (sm.red is only 64).
852	        float* red = &sm.adj_a[0][0];
853	        red[threadIdx.x] = tsum;
854	        __syncthreads();
855	        for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
856	            if (threadIdx.x < s) red[threadIdx.x] += red[threadIdx.x + s];
857	            __syncthreads();
858	        }
859	        if (threadIdx.x == 0) sq_part[cta] = red[0];
860	        bar.sync();   // B2.5a: all per-CTA sum-of-squares partials complete
861	        if (cta == 0 && threadIdx.x == 0) {
862	            double ss = 0.0;
863	            for (int c = 0; c < nCTA; ++c) ss += (double)sq_part[c];
864	            const float total_norm = sqrtf((float)ss);
865	            float coef = 1.0f;
866	            if (st.grad_clip > 0.0f && total_norm > st.grad_clip)
867	                coef = st.grad_clip / (total_norm + 1e-6f);
868	            *coef_bc = coef;
869	        }
870	        bar.sync();   // B2.5b: clip_coef broadcast slot ready for all CTAs
871	        st.clip_coef = *coef_bc;   // every CTA reads the single global coefficient
872	    }
