874	    // ── P2.6 (PRODIGY ONLY): STAGED cross-ALL-tensors d-estimate. PORT of the
875	    //    decoder/vit TC kernels' P2.6 (fused_decoder_megakernel.cuh:514-568) onto the
876	    //    mamba constant tables.
877	    //    ⚠ LANDED-DORMANT / NOT PRODUCTION-ROUTED: mamba×prodigy is BLOCKED on a
878	    //    PRE-EXISTING A/A/A determinism failure SHARED by the decoder/vit prodigy P2.6
879	    //    (this port faithfully reproduces them; the failure is NOT in this code). The
880	    //    dispatch.cpp mamba carve-out (optimizer!="prodigy") + the Python has_l3_real
881	    //    gate keep this branch unreachable from the race until the shared prodigy P2.6
882	    //    (opt_stages_precompute.cuh) / GridBarrier (megakernel_common.cuh) is fixed by
883	    //    its owner. Kept here (if-constexpr'd, proven byte-identical for every non-Prodigy
884	    //    Opt) as the ready starting point for that fix. See dispatch.py's ⚠ escalation.
885	    //    The apply tail (apply_optimizer<Prodigy>) reads
886	    //    st.d_factor (the effective LR scale d), a GLOBAL reduction over EVERY element
887	    //    of EVERY parameter tensor. We compute it here, BYTE-FAITHFUL to the live eager
888	    //    multi-tensor path (prodigy_sm90.cuh:465-544, the order prodigy.py →
889	    //    _ops.prodigy_fused_step actually executes):
890	    //      d_prev  = persisted d_lr  (step 1: d0 cold-start — the zero-init state slot
891	    //                would give d_prev=0 ⇒ d=0 ⇒ frozen params; eager inits _d_lr=d0,
892	    //                so seed it here, the grokfast-style step-1 fix)
893	    //      r_ema  <- beta3·r_ema + Σ d_prev²·<g, p0−p>     (decay persisted SCALAR,
894	    //      s_ema  <- beta3·s_ema + Σ d_prev²·|g|            then add this step's Σ)
895	    //      d       = max(d_prev, d_coef·r_ema/|s_ema|)      (prodigy_update_d; d_coef
896	    //                scales ONLY the candidate — persisted r_ema stays UNSCALED)
897	    //    DETERMINISM (COMPONENT_CONTRACT): NO float atomic. Each CTA publishes its
898	    //    (r,s) into per-CTA slots (opt_reduce) → grid barrier → CTA0 owner-sums in
899	    //    ascending index order → writes d back to the persisted slot + a broadcast
900	    //    slot. The decay is on the persisted SCALARS (not the per-CTA partials): the
901	    //    work-steal queue reassigns tensors to CTAs across steps, so a per-CTA EMA is
902	    //    undefined — the live form is a scalar EMA (prodigy_sm90.cuh:488). Guarded so
903	    //    every other opt's P3 is byte-identical (no extra barrier/work).
904	    // DETERMINISM — FIXED-PARTITION reduction (mirrors the A/A/A-CLEAN GrokAdamW
905	    // P2.5 + the decoder/vit twins' P2.6), NOT the work-steal task-queue drain.
906	    // WHY THIS SHAPE (the A/A/A determinism leg): the work-steal phaseA drained the
907	    // global TaskQueue (atomicAdd(g_next_task)) in timing-dependent claim order, so
908	    // each CTA's (r,s) slot could be a different tensor subset run-to-run; with non-
909	    // associative fp32 add the partials regroup differently and the owner's d can
910	    // differ at ULP level from step>=2 — a COMPONENT_CONTRACT deterministic-reduction
911	    // violation (not reproducible BY CONSTRUCTION). A FIXED contiguous element range
912	    // per CTA over the FLAT [0,kMambaTotalElems) arrays (params/param_init/grad are
913	    // parallel flat blobs → flat Σ == cross-tensor Σ) with a plain sync() is the
914	    // IDENTICAL shape as the A/A/A-CLEAN GrokAdamW P2.5 — deterministic by
915	    // construction. Per-element math still CALLS canonical prodigy_partials_step
916	    // (prodigy.h, single-source). g_next_task is UNTOUCHED (B2 reset it), so P3's
917	    // drain is unchanged — no sync_reset in P2.6. (mamba×prodigy is dispatch-gated to
918	    // eager today on a SEPARATE mamba scan/forward determinism issue; this keeps the
919	    // landed-dormant P2.6 correct + deterministic.)
920	    if constexpr (Opt == OptId::Prodigy) {
921	        float* r_part = opt_reduce;                  // [nCTA] per-CTA Σ d²·<g,p0−p>
922	        float* s_part = opt_reduce + nCTA;           // [nCTA] per-CTA Σ d²·|g|
923	        float* d_bc   = opt_reduce + 2 * nCTA;       // [1] reduced-d broadcast
924	        const float d_prev = (step == 1) ? st.d0 : st.prodigy_persist[2];
925	        const int64_t total_p = kMambaTotalElems;
926	        const int64_t pbase = total_p / nCTA, prem = total_p % nCTA;
927	        const int64_t pe0 = (int64_t)cta * pbase + (cta < prem ? cta : prem);
928	        const int64_t pecnt = pbase + (cta < prem ? 1 : 0);
929	        float r_acc = 0.0f, s_acc = 0.0f;
930	        for (int64_t i = threadIdx.x; i < pecnt; i += blockDim.x) {
931	            algo::prodigy_partials_step(params, st.param_init, grad,
932	                                        d_prev, pe0 + i, r_acc, s_acc);
933	        }
934	        float r_block, s_block;
935	        prim::block_reduce_sum2_f32(r_acc, s_acc, r_block, s_block);
936	        if (threadIdx.x == 0) { r_part[cta] = r_block; s_part[cta] = s_block; }
937	        bar.sync();   // B2.6a: all per-CTA (r,s) partials published & visible
938	        if (cta == 0 && threadIdx.x == 0) {
939	            float r_step = 0.0f, s_step = 0.0f;     // ascending-CTA owner-sum
940	            for (int c = 0; c < nCTA; ++c) { r_step += r_part[c]; s_step += s_part[c]; }
941	            const float r_ema = st.beta3 * st.prodigy_persist[0] + r_step;
942	            const float s_ema = st.beta3 * st.prodigy_persist[1] + s_step;
943	            const float d_new = algo::prodigy_update_d(d_prev, st.d_coef * r_ema, s_ema);
944	            st.prodigy_persist[0] = r_ema;          // persist UNSCALED EMA
945	            st.prodigy_persist[1] = s_ema;
946	            st.prodigy_persist[2] = d_new;          // persisted d_lr for next step
947	            d_bc[0]               = d_new;          // broadcast to all CTAs
948	        }
949	        bar.sync();   // B2.6b: d visible to every CTA before the apply
950	        st.d_factor = d_bc[0];                      // the reduced d the tail reads
951	    }
952	
953	    // ── P2.7 (Muon ONLY): grid-cooperative Newton-Schulz orthogonalization of the
954	    //    2D weights (INTEGRATION-OPTSTAGES §3). PORT of the decoder/vit twins' P2.7
955	    //    (fused_decoder_megakernel.cuh / fused_vit_megakernel.cuh) onto the mamba
956	    //    constant tables — same shared opt_stages_precompute.cuh helpers, same barrier
957	    //    sequence; only the per-model 2D table (mbtc::kMbMuon2D, 13 matrices incl.
958	    //    tok[99,128]/pos[8,128]/A_log[256,16]/dt_proj[256,8]/x_proj[40,256]) and offset
959	    //    array (kMambaOffsets) differ. For EACH 2D matrix all CTAs cooperate: buf=μ·buf+g
960	    //    (buf is the PERSISTENT m-slice — momentum state, NOT transient), ‖buf‖_F via
961	    //    per-CTA partials → inv_norm, X=buf·inv_norm, then ns_steps × { A=XXᵀ → AX=A·X →
962	    //    AAX=A·AX → orth=a·X+b·AX+c·AAX, swap }, then the canonical muon_update_step apply
963	    //    (decay·p + neg_lr_scale·orth). The 1D / non-2D weights (D, conv1d.weight/bias,
964	    //    dt_proj.bias, LN γ/β, out.bias) take the AdamW aux tail in P3. The elementwise
965	    //    bodies CALL muon.h (muon_momentum_normalize_step via the phaseA buf body,
966	    //    muon_ns_combine_step, muon_update_step); the matmuls are the cited new device
967	    //    code (the eager path delegates to torch::mm/cuBLAS). Guarded so every other opt is
968	    //    byte-identical (no extra barriers / work).
969	    //    DETERMINISM (the A/A/A leg the gate verifies): muon/mamba is a SINGLE forward +
970	    //    NS precompute — it does NOT re-run the mamba forward (unlike the SAM-2nd-pass
971	    //    mamba cells looksam/SG11/15 which hit the shared mamba-forward A/A/A race), and the
972	    //    P2.7 reductions are fixed-ownership ascending-CTA (muon_norm_reduce_phaseB sums
973	    //    nrm_partials[0..nCTA) in ascending index) + the NS matmuls are deterministic
974	    //    grid-cooperative tiles — so the phase is deterministic BY CONSTRUCTION. The gate
975	    //    confirms A/A/A bit-identity; if it ever fails, the cell is landed-dormant (see
976	    //    the dispatch.cpp mb_muon carve-out scaffold).
977	    if constexpr (Opt == OptId::Muon) {
978	        // Carve the per-matrix NS scratch (sized for the largest 2D weight).
979	        PrecomputeWorkspace pw{};
980	        pw.muon_X            = muon_base;
981	        pw.muon_AX           = pw.muon_X   + mbtc::kMbMuonMaxNumel;
982	        pw.muon_AAX          = pw.muon_AX  + mbtc::kMbMuonMaxNumel;
983	        pw.muon_orth         = pw.muon_AAX + mbtc::kMbMuonMaxNumel;
984	        pw.muon_A            = pw.muon_orth + mbtc::kMbMuonMaxNumel;
985	        pw.muon_nrm_partials = pw.muon_A   + (int64_t)mbtc::kMbMuonMaxRows * mbtc::kMbMuonMaxRows;
986	        pw.muon_inv_norm     = pw.muon_nrm_partials + nCTA;
987	        const float momentum = st.beta1;          // Muon momentum (eager Muon: betas[0])
988	        const int   ns_steps = 5;                 // bindings.cpp default
989	        for (int mi = 0; mi < mbtc::kMbNumMuon2D; ++mi) {
990	            const mbtc::MbMuon2D M = mbtc::kMbMuon2D[mi];
991	            const int rows = M.rows, cols = M.cols;
992	            const int64_t numel = (int64_t)rows * cols;
993	            const int64_t off   = (int64_t)kMambaOffsets[M.tidx];
994	            // buf = the PERSISTENT momentum slice for this matrix (st.exp_avg+off).
995	            pw.muon_buf = st.exp_avg + off;
996	            // phaseA: buf=μ·buf+g, publish per-CTA ‖buf‖_F² → reduce → inv_norm → X.
997	            muon_momentum_norm_phaseA(grad + off, numel, momentum, pw);
998	            bar.sync();
999	            muon_norm_reduce_phaseB(ctx, pw);
1000	            bar.sync();
1001	            muon_scale_X(numel, pw);
1002	            bar.sync();
1003	            // NS iterations. After each combine, orth holds the new iterate; swap so
1004	            // the next iteration reads it as X. ns_steps swaps → final result is in
1005	            // muon_X (the last combine wrote muon_orth, then we swapped → muon_X).
1006	            for (int s = 0; s < ns_steps; ++s) {
1007	                // A = X Xᵀ  (M=rows,N=rows,K=cols; B transposed).
1008	                muon_matmul(pw.muon_X, pw.muon_X, pw.muon_A, rows, rows, cols, cols, cols, /*bT=*/true);
1009	                bar.sync();
1010	                // AX = A X   (M=rows,N=cols,K=rows).
1011	                muon_matmul(pw.muon_A, pw.muon_X, pw.muon_AX, rows, cols, rows, rows, cols, /*bT=*/false);
1012	                bar.sync();
1013	                // AAX = A (AX) (M=rows,N=cols,K=rows).
1014	                muon_matmul(pw.muon_A, pw.muon_AX, pw.muon_AAX, rows, cols, rows, rows, cols, /*bT=*/false);
1015	                bar.sync();
1016	                muon_ns_combine_phase(numel, pw);   // orth = a·X + b·AX + c·AAX
1017	                bar.sync();
1018	                float* tmp = pw.muon_X; pw.muon_X = pw.muon_orth; pw.muon_orth = tmp;
1019	            }
1020	            // Apply Muon: p = decay_factor·p + neg_lr_scale·orth  (muon.h:63-73).
1021	            const float scale        = 0.2f * sqrtf((float)(rows > cols ? rows : cols));
1022	            const float neg_lr_scale = -lr * scale;
1023	            const float decay_factor = 1.0f - lr * st.wd;
1024	            float* __restrict__ p = params + off;
1025	            const float* __restrict__ orth_final = pw.muon_X;   // post-swap result
1026	            const int64_t gstride = (int64_t)blockDim.x * gridDim.x;
1027	            for (int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x; i < numel; i += gstride)
1028	                p[i] = decay_factor * p[i] + neg_lr_scale * orth_final[i];
1029	            bar.sync();   // matrix done; all CTAs synchronized before the next matrix
1030	        }
1031	    }
1032	
1033	    // ── P2.45 (SuperGrok11/15 ONLY) staged into P3: the per-TENSOR meta-net mu
1034	    //    precompute (INTEGRATION-OPTSTAGES §4/§5) — PORT of the decoder/vit twins'
1035	    //    P2.45 onto the mamba constant tables. SINGLE task-queue drain, NO grid
1036	    //    barrier: each tensor T is SELF-CONTAINED — mu(T) = sg_rescale·phi(g[T],
1037	    //    sharpness[T]) (per element) and, for SG11, the per-tensor gate(T) =
1038	    //    sigmoid(gate_temp·cos(g[T], mu[T])) depend ONLY on T's own elements, so mu(+gate)→
1039	    //    apply fuse into ONE body the SAME CTA owns end-to-end inside the EXISTING P3
1040	    //    drain. The phi weights (per-TENSOR weight set) are staged to SMEM ONCE per
1041	    //    block before the drain. SG15's gate is the host scalar st.gate (no cosine
1042	    //    stage); SG11 binds the per-tensor gate the helper returns. sharpness (the 2nd
1043	    //    MLP input) was produced by P2.4 (or the cached prior step).
1044	    __shared__ float sg_sW1[kSgPhiHidden * 2];
1045	    __shared__ float sg_sb1[kSgPhiHidden];
1046	    __shared__ float sg_sW2[kSgPhiHidden];
1047	    if constexpr (Opt == OptId::SuperGrok11 || Opt == OptId::SuperGrok15) {
1048	        sg_stage_phi_weights<kSgPhiHidden>(st.sg_phi_W1, st.sg_phi_b1, st.sg_phi_W2,
1049	                                           sg_sW1, sg_sb1, sg_sW2);   // syncs
1050	    }
1051	
1052	    // ── P3-SG2 (SuperGrok2 ONLY): the FULL CSA/HCA/PEER/GRU meta-net as the optimizer
1053	    //    phase — PORT of the decoder/vit twins' P3-SG2 onto the mamba constant tables.
1054	    //    Run INSTEAD of the per-element apply_optimizer<SuperGrok2> (which is only the
1055	    //    Adam-on-smart_grad stub). Each CTA work-steals WHOLE tensors from the queue
1056	    //    (reset at B2 / B2.4g) and runs sg2_meta_stages for each tensor end-to-end:
1057	    //    STAGE -1 in-kernel segmented sort (|grad| ascending, index tie-break — strategy
1058	    //    A) → S0..S5 (input-proj, CSA, HCA, GRU, PEER, apply). The SAM-written
1059	    //    st.sharpness (P2.4, (g_sam−g)²) is the meta-net's 2nd MLP input (sharp_base).
1060	    //    The meta-net WEIGHTS come from HBM — sg2_meta_stages is instantiated with
1061	    //    WeightsT==SG2Weights + BuildSort=true. The per-tensor intermediates + the
1062	    //    segmented-sort scratch live in this CTA's slice of the SG2 workspace (carve-
1063	    //    LAST, after the Muon NS scratch). This whole phase is if-constexpr'd to
1064	    //    SuperGrok2, so every other cell is byte-identical (no extra barrier/work). The
1065	    //    kernel returns after this — no trailing grid barrier (each tensor is CTA-local).
1066	    //    ⚠ A/A/A: the SAM double-forward + segmented sort re-exercise the shared mamba
1067	    //    forward (the .sg2_spec.md-flagged risk). The gate re-verifies A/A/A; if it trips
1068	    //    the race, mamba×supergrok2 lands DORMANT (dispatch-gated to eager).
1069	    if constexpr (Opt == OptId::SuperGrok2) {
1070	        // Reconstruct the SG2 weight bundle (HBM pointers) from the threaded fields.
1071	        SG2Weights w2{
1072	            st.sg2_input_proj_W, st.sg2_input_proj_b,
1073	            st.sg2_csa_q_W, st.sg2_csa_k_W, st.sg2_csa_v_W, st.sg2_csa_out_W,
1074	            st.sg2_csa_compress_w, st.sg2_csa_idx_DQ, st.sg2_csa_idx_K,
1075	            st.sg2_hca_q_W, st.sg2_hca_k_W, st.sg2_hca_v_W, st.sg2_hca_out_W,
1076	            st.sg2_gru_Wz, st.sg2_gru_bz, st.sg2_gru_Wr, st.sg2_gru_br,
1077	            st.sg2_gru_Wh, st.sg2_gru_bh,
1078	            st.sg2_peer_query_Ws, st.sg2_prod_keys_A, st.sg2_prod_keys_B,
1079	            st.sg2_expert_W1, st.sg2_expert_b1, st.sg2_expert_W2, st.sg2_expert_b2};
1080	        SG2Scalars sc2{
1081	            st.sg2_alpha, st.sg2_gru_decay, st.sg2_lamb_eff,
1082	            st.sg2_beta1, st.sg2_bc1, st.sg2_bc2,
1083	            st.sg2_rescale, st.beta2, lr, st.wd, st.eps};
1084	        // Stage row_off (int64) for the SG2State adapter once into the FRONT of this
1085	        // CTA's SG2 workspace slice (kMambaOffsets is __constant__ int; SG2State.row_off
1086	        // wants const int64_t*). All CTAs stage their own copy (cheap, kMambaNumTensors).
1087	        float* sg2_base = sg2_ws_base + (int64_t)blockIdx.x * mb_sg2_ws_stride_floats();
1088	        int64_t* row_off64 = reinterpret_cast<int64_t*>(sg2_base);
1089	        for (int t = threadIdx.x; t < kMambaNumTensors; t += blockDim.x)
1090	            row_off64[t] = (int64_t)kMambaOffsets[t];
1091	        // The meta-net scratch starts AFTER the row_off64 staging block: reserve
1092	        // kMambaNumTensors int64 = 2*N floats.
1093	        float* sg2_meta_ws = sg2_base + 2 * kMambaNumTensors;
1094	        __syncthreads();
1095	        SG2State stt{};
1096	        stt.exp_avg     = st.exp_avg;
1097	        stt.exp_avg_sq  = st.exp_avg_sq;
1098	        stt.mu          = const_cast<float*>(st.mu);
1099	        stt.slow        = st.sg2_slow;
1100	        stt.gru_state   = st.sg2_gru_state;
1101	        stt.perm        = nullptr;          // built in-kernel (BuildSort=true)
1102	        stt.unsort      = nullptr;
1103	        stt.workspace   = sg2_meta_ws;
1104	        stt.ws_stride   = sg2_ws_stride<MbSG2Dims>((int64_t)kMbSG2Nmax);
1105	        stt.n_tensors   = kMambaNumTensors;
1106	        stt.n           = kMambaSizes;      // __constant__ int[]
1107	        stt.row_off     = row_off64;
1108	        __shared__ int task_slot2;
1109	        TaskQueue q2 = ctx.queue();
1110	        for (int t = q2.next_block(&task_slot2); t < kMambaNumTensors;
1111	             t = q2.next_block(&task_slot2)) {
1112	            sg2_meta_stages<MbSG2Dims, SG2Weights, float, float, /*BuildSort=*/true>(
1113	                w2, t, stt, sc2, params, grad, st.sharpness, sg2_meta_ws);
1114	        }
1115	        SG_MBTC_PROF_ACC(3, _pt);          // close P3 (SG2 owns the optimizer phase)
1116	        return;   // SG2 owns the whole optimizer phase; skip P3.
1117	    }
1118	
1119	    // ── P3: the REAL optimizer tail over the reduced grad (work-steal 28). ──
1120	    st.lr = lr;
1121	    {
1122	        __shared__ int task_slot;
1123	        TaskQueue q = ctx.queue();
1124	        for (int t = q.next_block(&task_slot); t < kMambaNumTensors;
1125	             t = q.next_block(&task_slot)) {
1126	            const int n = kMambaSizes[t];
1127	            const int64_t off = (int64_t)kMambaOffsets[t];
1128	            // MUON: the 2D matrices were orthogonalized + applied in P2.7; P3 handles
1129	            //   ONLY the 1D / non-2D weights, which take the AdamW tail (muon.h:75-76,
1130	            //   the eager Muon auto-split). Skip the 2D ones here (already done).
1131	            if constexpr (Opt == OptId::Muon) {
1132	                if (mbtc::mb_is_muon_2d(t)) continue;
1133	            }
1134	            FusedOptState ts = mamba_rebase_state<Opt>(st, off);
1135	            // (i) PER-TENSOR LAYER-WISE β1 (GrokAdamW only) — PORT of the decoder
1136	            //     P3 (fused_decoder_megakernel.cuh:587-591): β1_i = β1·(1-γ)^t, where
1137	            //     t == the tensor's flat named_parameters() layer index (the work-steal
1138	            //     task id maps 1:1 to kMambaOffsets order == the eager enumeration
1139	            //     order, so t IS the eager layer index). bc1 must be rebased TOO
1140	            //     (= 1-β1_i^step) or m_hat=m/bc1 mismatches eager; bc2 stays global
1141	            //     (β2 is not layer-wise). This is the mechanism that fails the STEP-1
1142	            //     STATE gate when dropped (decoder observed m-rel 0.895).
1143	            if constexpr (Opt == OptId::GrokAdamW) {
1144	                const float b1 = st.beta1 * powf(1.0f - st.gamma, (float)t);
1145	                ts.beta1 = b1;
1146	                ts.bc1   = 1.0f - powf(b1, (float)step);
1147	            }
1148	            // SuperGrok11/15 meta-net mu (+ SG11 per-tensor gate) precompute for THIS
1149	            // tensor, BEFORE the apply reads ts.mu/ts.gate — PORT of the decoder/vit P3.
1150	            // mu(T)=sg_rescale·phi(g,sharpness) over [off,off+n); SG11 also computes the
1151	            // gate(T)=sigmoid(gate_temp·cos) (block-uniform __syncthreads/reduce — the whole CTA
1152	            // owns t). SG15's gate is st.gate (host sigmoid(accuracy)). Helpers index
1153	            // grad/sharpness/mu by off+i, so pass the BASE pointers (st.mu, grad,
1154	            // st.sharpness) + off; the apply then reads ts.mu (== st.mu+off). phi_b2 read
1155	            // on-device from sg_phi_W2[H].
1156	            if constexpr (Opt == OptId::SuperGrok11) {
1157	                const float b2 = (st.sg_phi_W2 != nullptr) ? st.sg_phi_W2[kSgPhiHidden]
1158	                                                           : st.sg_phi_b2;
1159	                // st.exp_avg = start-of-step momentum (base ptr, indexed by off+i) —
1160	                // the gate's 2nd cosine operand: sigmoid(gate_temp·cos(grad,momentum)).
1161	                // Precompute runs BEFORE the apply (sg11_sweep_b_step) writes exp_avg.
1162	                const float g8 = sg11_precompute_mu_and_gate_for_tensor<kSgPhiHidden>(
1163	                    st.mu, grad, st.sharpness, st.exp_avg, sg_sW1, sg_sb1, sg_sW2,
1164	                    b2, st.sg_rescale, off, n, st.gate_temp);
1165	                ts.gate = g8;            // per-tensor gate=sigmoid(gate_temp·cos) the apply tail reads
1166	                __syncthreads();         // mu(T) fully written + gate broadcast before apply
1167	            } else if constexpr (Opt == OptId::SuperGrok15) {
1168	                const float b2 = (st.sg_phi_W2 != nullptr) ? st.sg_phi_W2[kSgPhiHidden]
1169	                                                           : st.sg_phi_b2;
1170	                sg15_precompute_mu_for_tensor<kSgPhiHidden>(
1171	                    st.mu, grad, st.sharpness, sg_sW1, sg_sb1, sg_sW2,
1172	                    b2, st.sg_rescale, off, n);
1173	                // ts.gate stays = st.gate (the host sigmoid(accuracy) scalar).
1174	                __syncthreads();         // mu(T) visible before the apply reads it
1175	            }
1176	            float* __restrict__ p = params + off;
1177	            const float* __restrict__ gg = grad + off;
1178	            if constexpr (Opt == OptId::Muon) {
1179	                // 1D / non-2D weights: the canonical AdamW tail (muon.py:99-125 routes
1180	                // non-matrix params to a SEPARATE AdamW group with INDEPENDENT
1181	                // hyperparameters — adamw_lr/adamw_betas — NOT the 2D Muon lr/momentum).
1182	                // ts.lr/ts.beta1 carry the 2D-group's (lr=0.02, momentum=0.95), so the
1183	                // 1D tail MUST instead use the aux_* fields (eager adamw_lr/adamw_betas).
1184	                // weight_decay is SHARED across both eager groups (muon.py:122) → ts.wd
1185	                // stays. eps is the eager adamw_eps (= ts.eps, mapped by _opt_scalars_from).
1186	                // bc1/bc2 are device-computed from aux_beta^step (kept out of the mirror
1187	                // to shrink the host ABI; fp32 powf, tol 2e-3 ample). apply_optimizer<Muon>
1188	                // would deref st.orth (NS dir, only valid for 2D), so route directly to
1189	                // adamw_step with the aux hyperparameters — IDENTICAL to the decoder/vit twins.
1190	                const float a_bc1 = 1.0f - powf(st.aux_beta1, (float)step);
1191	                const float a_bc2 = 1.0f - powf(st.aux_beta2, (float)step);
1192	                for (int i = threadIdx.x; i < n; i += blockDim.x)
1193	                    algo::adamw_step<float, float>(
1194	                        p, ts.exp_avg, ts.exp_avg_sq, gg,
1195	                        st.aux_lr, st.aux_beta1, st.aux_beta2, ts.eps, ts.wd,
1196	                        a_bc1, a_bc2, (int64_t)i);
1197	            } else {
1198	                for (int i = threadIdx.x; i < n; i += blockDim.x)
1199	                    apply_optimizer<Opt>(p, gg, (int64_t)i, step, ts);
1200	            }
1201	        }
1202	    }
1203	    SG_MBTC_PROF_ACC(3, _pt);          // close P3
1204	}
