877	// ════════════════════════════════════════════════════════════════════════
878	//  FORWARD for one sample (CTA-cooperative). Mirrors mamba3_oracle.model_forward
879	//  + block_forward. Caches BOTH blocks' activations into sm->act[li]. Returns NLL.
880	// ════════════════════════════════════════════════════════════════════════
881	__device__ inline float mb_forward_sample(const MambaWeights& w, const int* tokens_s,
882	                                    int target, MambaSampleSmem* sm) {
883	    // Embedding + positional -> layer_in[0].
884	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kD; idx += blockDim.x) {
885	        const int s = idx / mb::kD, j = idx % mb::kD;
886	        sm->layer_in[0][s][j] = w.tok[(int64_t)tokens_s[s] * mb::kD + j]
887	                              + w.pos[(int64_t)s * mb::kD + j];
888	    }
889	    __syncthreads();
890	
891	    for (int li = 0; li < mb::kLayers; ++li) {
892	        const MambaWeights::Layer& L = w.layer[li];
893	        MambaSampleSmem::LayerAct* a = &sm->act[li];
894	        float* hin = &sm->layer_in[li][0][0];   // block input (residual)
895	        // --- mixer sub-block: h1 = hin + mixer(RMSNorm_mix(hin)) ---
896	        // xhat written to throwaway scratch (adj_c) — only the recip is cached; the
897	        // backward recomputes xhat from the raw block input layer_in[li].
898	        mb_rmsnorm_fwd(hin, L.mixn_w, &sm->dr[0][0], &sm->adj_c[0][0], &a->mixn_r[0],
899	                       sm->red, mb::kD, mb::kD);   // xn -> sm->dr
900	        // mix_out written into adj_b at WIDTH-kD stride (s*kD+j); read it the same way.
901	        float* mo = &sm->adj_b[0][0];
902	        mb_mixer_fwd(L, &sm->dr[0][0], a, mo, sm);   // mix_out -> sm->adj_b (kD-strided)
903	        for (int idx = threadIdx.x; idx < mb::kSeq * mb::kD; idx += blockDim.x) {
904	            const int s = idx / mb::kD, j = idx % mb::kD;
905	            a->h1[s][j] = hin[s * mb::kD + j] + mo[s * mb::kD + j];   // h1 = x + mixer_out
906	        }
907	        __syncthreads();
908	        // --- SwiGLU sub-block: h2 = h1 + mlp(RMSNorm_mlp(h1)) ---
909	        // xhat throwaway (adj_c); backward recomputes from the raw h1.
910	        mb_rmsnorm_fwd(&a->h1[0][0], L.mlpn_w, &sm->dr[0][0], &sm->adj_c[0][0], &a->mlpn_r[0],
911	                       sm->red, mb::kD, mb::kD);   // h1n -> sm->dr
912	        mb_swiglu_fwd(L, &sm->dr[0][0], a, mo, sm);  // mlp_out -> sm->adj_b (kD-strided)
913	        float* dst = (li + 1 < mb::kLayers) ? &sm->layer_in[li + 1][0][0] : &sm->final_in[0][0];
914	        for (int idx = threadIdx.x; idx < mb::kSeq * mb::kD; idx += blockDim.x) {
915	            const int s = idx / mb::kD, j = idx % mb::kD;
916	            dst[s * mb::kD + j] = a->h1[s][j] + mo[s * mb::kD + j];   // h2 = h1 + mlp_out
917	        }
918	        __syncthreads();
919	    }
920	
921	    // Final RMSNorm (LAST position) + head -> logits -> NLL.
922	    const float* hlast = &sm->final_in[mb::kSeq - 1][0];
923	    float ss = 0.0f;
924	    for (int j = threadIdx.x; j < mb::kD; j += blockDim.x) { float v = hlast[j]; ss += v * v; }
925	    float ms = mb_block_sum(ss, sm->red) / (float)mb::kD;
926	    float r = rsqrtf(ms + mb::kRmsEps);
927	    if (threadIdx.x == 0) sm->fn_r[mb::kSeq - 1] = r;
928	    for (int j = threadIdx.x; j < mb::kD; j += blockDim.x) {
929	        float xh = hlast[j] * r;
930	        sm->fn_xhat[mb::kSeq - 1][j] = xh;
931	        sm->adj_a[0][j] = xh * w.norm_w[j];   // hn (RMSNorm, NO bias) -> adj_a[0]
932	    }
933	    __syncthreads();
934	    for (int o = threadIdx.x; o < mb::kPHead; o += blockDim.x) {
935	        const float* Wr = w.out_w + (int64_t)o * mb::kD;
936	        float acc = w.out_b[o];
937	        #pragma unroll 4
938	        for (int k = 0; k < mb::kD; ++k) acc += sm->adj_a[0][k] * Wr[k];
939	        sm->logits[o] = acc;
940	    }
941	    __syncthreads();
942	    float lmax = -CUDART_INF_F;
943	    for (int o = threadIdx.x; o < mb::kPHead; o += blockDim.x) lmax = fmaxf(lmax, sm->logits[o]);
944	    lmax = mb_block_max(lmax, sm->red);
945	    float es = 0.0f;
946	    for (int o = threadIdx.x; o < mb::kPHead; o += blockDim.x) es += __expf(sm->logits[o] - lmax);
947	    es = mb_block_sum(es, sm->red);
948	    float logz = lmax + __logf(es);
949	    return logz - sm->logits[target];
950	}
951	
952	// ════════════════════════════════════════════════════════════════════════
953	//  MIXER backward for one sample (CTA-cooperative, residual OFF). Given dmix_out
954	//  [kSeq,d] (= dL/d(mixer output)), accumulates the mixer's weight grads into G
955	//  and writes dxn [kSeq,d] (grad wrt the mixer INPUT = RMSNorm_mix(x)). Mirrors
956	//  mamba3_oracle.layer_backward (residual path handled by the block).
957	//  Scratch contract on entry: sm->dr holds the mixer's recomputed input xn
958	//  (re-staged by the caller). Uses adj_a/b/c, xproj, dBbar/dCbar/dtheta.
959	// ════════════════════════════════════════════════════════════════════════
960	__device__ inline void mb_mixer_bwd(const MambaWeights::Layer& L, const MambaGrad::Layer& G,
961	                            const float* __restrict__ xn,    // [kSeq,d] mixer input (recomputed)
962	                            MambaSampleSmem::LayerAct* a,
963	                            const float* __restrict__ dmix_out,  // [kSeq,d]
964	                            float* __restrict__ dxn,         // [kSeq,d] OUT
965	                            MambaSampleSmem* sm) {
966	    // Recompute y_gated -> sm->adj_a (out_proj input). y_gated = (y_scan + x_in*D)*silu(z).
967	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kDInner; idx += blockDim.x) {
968	        const int s = idx / mb::kDInner, c = idx % mb::kDInner;
969	        float yv = a->y_scan[s][c] + a->x_in[s][c] * L.D[c];
970	        sm->adj_a[s][c] = yv * mb_silu(a->z[s][c]);
971	    }
972	    __syncthreads();
973	    // out_proj bwd: dW_out += dmix_out^T @ y_gated ; dy_gated = dmix_out @ out_w -> adj_c.
974	    mb_linear_bwd(dmix_out, mb::kD, &sm->adj_a[0][0], mb::kDInner, L.out_w,
975	                  mb::kDInner, mb::kD, G.out_w, nullptr, &sm->adj_c[0][0], mb::kDInner, true);
976	    // gate+skip bwd. y_gated=y_skip*silu(z); y_skip=y_scan + x_in*D.
977	    //   dy_skip = dy_gated*sz ; dsz = dy_gated*y_skip ; dz = dsz*silu'(z).
978	    //   dy_scan = dy_skip ; dx_in(D-path) = dy_skip*D ; dD += Σ dy_skip*x_in.
979	    //   dz -> sm->wff_b (NOT adj_a — the BCNorm bwd below clobbers adj_a; wff_b is
980	    //   free in the mixer bwd and kDff>=kDInner wide). adj_b := dy_scan (scan dy).
981	    for (int c = threadIdx.x; c < mb::kDInner; c += blockDim.x) {
982	        float dDc = 0.0f;
983	        #pragma unroll
984	        for (int s = 0; s < mb::kSeq; ++s) {
985	            float sz = mb_silu(a->z[s][c]);
986	            float xm = a->x_in[s][c];
987	            float yskip = a->y_scan[s][c] + xm * L.D[c];
988	            float dyg = sm->adj_c[s][c];
989	            float dyskip = dyg * sz;
990	            float dsz = dyg * yskip;
991	            sm->wff_b[s][c] = dsz * mb_silu_grad(a->z[s][c]);   // dz (survives BCNorm)
992	            dDc += dyskip * xm;
993	            sm->adj_b[s][c] = dyskip;          // dy_scan (D-path added back later)
994	        }
995	        G.D[c] += dDc;
996	    }
997	    __syncthreads();
998	    // selective scan bwd. dy_scan = adj_b. Zero the head-shared reduce buffers first.
999	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kStateC; idx += blockDim.x) {
1000	        const int s = idx / mb::kStateC, c = idx % mb::kStateC;
1001	        sm->dBbar[s][c][0] = 0.f; sm->dBbar[s][c][1] = 0.f;
1002	        sm->dCbar[s][c][0] = 0.f; sm->dCbar[s][c][1] = 0.f;
1003	        sm->dtheta[s][c] = 0.f;
1004	    }
1005	    __syncthreads();
1006	    // scan bwd outputs: dx_in (scan path) -> sm->wff_b rows [0,d_inner) of row 0..? No:
1007	    //   route dx_in (scan path) -> sm->adj_c[s][c] (dy_gated consumed). per-head grads
1008	    //   -> sm->wff_a (3 blocks of kSeq*n_heads); dBbar/dCbar/dtheta -> smem reduce bufs;
1009	    //   dA_log -> G.A_log (per head).
1010	    float* ddt_pre_s = &sm->wff_a[0][0];                          // [kSeq,n_heads]
1011	    float* dA_mod_s  = &sm->wff_a[0][0] + mb::kSeq * mb::kNHeads;  // [kSeq,n_heads]
1012	    float* du_lam_s  = dA_mod_s + mb::kSeq * mb::kNHeads;          // [kSeq,n_heads]
1013	    mb_scan_bwd(L.A_log, a, &sm->adj_b[0][0],
1014	                &sm->adj_c[0][0],      // dx_in (scan path) SET (dy_gated consumed)
1015	                ddt_pre_s, dA_mod_s, du_lam_s,
1016	                &sm->dBbar[0][0][0], &sm->dCbar[0][0][0], &sm->dtheta[0][0],
1017	                G.A_log, sm->red);
1018	    // dx_in total = scan-path (adj_c) + D-path (dy_skip*D, dy_skip in adj_b) -> adj_c.
1019	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kDInner; idx += blockDim.x) {
1020	        const int s = idx / mb::kDInner, c = idx % mb::kDInner;
1021	        sm->adj_c[s][c] += sm->adj_b[s][c] * L.D[c];   // dx_in = scan + D path
1022	    }
1023	    __syncthreads();
1024	    // dt_proj bwd: dW_dt += ddt_pre^T @ dt_lr ; db_dt += Σ ddt_pre ;
1025	    //   ddt_lr = ddt_pre @ dt_proj_w -> staged into sm->xproj[:, kOffDtLr..dt_rank).
1026	    mb_linear_bwd(ddt_pre_s, mb::kNHeads, &a->dt_lr[0][0], mb::kDtRank, L.dt_proj_w,
1027	                  mb::kDtRank, mb::kNHeads, G.dt_proj_w, G.dt_proj_b,
1028	                  &sm->xproj[0][mb::kOffDtLr], mb::kXProj, true);
1029	    // dA_mod -> xproj[:, kOffAmod..) ; dtheta (smem) -> xproj[:, kOffThet..) ;
1030	    // du_lam -> xproj[:, kOffULam..).  (theta is a direct slice of x_proj output.)
1031	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kNHeads; idx += blockDim.x) {
1032	        const int s = idx / mb::kNHeads, hh = idx % mb::kNHeads;
1033	        sm->xproj[s][mb::kOffAmod + hh] = dA_mod_s[s * mb::kNHeads + hh];
1034	        sm->xproj[s][mb::kOffULam + hh] = du_lam_s[s * mb::kNHeads + hh];
1035	    }
1036	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kStateC; idx += blockDim.x) {
1037	        const int s = idx / mb::kStateC, c = idx % mb::kStateC;
1038	        sm->xproj[s][mb::kOffThet + c] = sm->dtheta[s][c];
1039	    }
1040	    __syncthreads();
1041	    // BCNorm backward for each stream. Cbar=(Cr2,-Ci2): dCr2=dCbar0, dCi2=-dCbar1.
1042	    //   Bbar=(Br2,Bi2): dBr2=dBbar0, dBi2=dBbar1. Each stream: bias grad = Σ_s d*2;
1043	    //   then RMSNorm bwd (raw pre-norm input x = a->Br/Bi/Cr/Ci, recip = *_r).
1044	    //   The staged d*2 lands in `an` at WIDTH-kStateC stride (s*Nc+c) so the
1045	    //   rmsnorm-bwd (which reads dy at that stride) + the bias reduce agree.
1046	    //   dBr -> xproj[:, kOffBr..); dBi -> kOffBi; dCr -> kOffCr; dCi -> kOffCi.
1047	    float* anb = &sm->adj_a[0][0];
1048	    // --- B real (dBr2 = dBbar0) ---
1049	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kStateC; idx += blockDim.x) {
1050	        const int s = idx / mb::kStateC, c = idx % mb::kStateC;
1051	        anb[s * mb::kStateC + c] = sm->dBbar[s][c][0];
1052	    }
1053	    __syncthreads();
1054	    for (int c = threadIdx.x; c < mb::kStateC; c += blockDim.x) {
1055	        float acc = 0.f; for (int s = 0; s < mb::kSeq; ++s) acc += anb[s * mb::kStateC + c];
1056	        G.B_bias[c] += acc;
1057	    }
1058	    __syncthreads();
1059	    mb_rmsnorm_bwd_rawx(anb, &a->Br[0][0], &a->Br_r[0], L.B_norm_w,
1060	                        &sm->xproj[0][mb::kOffBr], G.B_norm_w, sm->red, mb::kStateC, mb::kXProj);
1061	    __syncthreads();
1062	    // --- B imag (dBi2 = dBbar1) ---
1063	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kStateC; idx += blockDim.x) {
1064	        const int s = idx / mb::kStateC, c = idx % mb::kStateC;
1065	        anb[s * mb::kStateC + c] = sm->dBbar[s][c][1];
1066	    }
1067	    __syncthreads();
1068	    for (int c = threadIdx.x; c < mb::kStateC; c += blockDim.x) {
1069	        float acc = 0.f; for (int s = 0; s < mb::kSeq; ++s) acc += anb[s * mb::kStateC + c];
1070	        G.Bhat_bias[c] += acc;
1071	    }
1072	    __syncthreads();
1073	    mb_rmsnorm_bwd_rawx(anb, &a->Bi[0][0], &a->Bi_r[0], L.Bhat_norm_w,
1074	                        &sm->xproj[0][mb::kOffBi], G.Bhat_norm_w, sm->red, mb::kStateC, mb::kXProj);
1075	    __syncthreads();
1076	    // --- C real (dCr2 = dCbar0) ---
1077	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kStateC; idx += blockDim.x) {
1078	        const int s = idx / mb::kStateC, c = idx % mb::kStateC;
1079	        anb[s * mb::kStateC + c] = sm->dCbar[s][c][0];
1080	    }
1081	    __syncthreads();
1082	    for (int c = threadIdx.x; c < mb::kStateC; c += blockDim.x) {
1083	        float acc = 0.f; for (int s = 0; s < mb::kSeq; ++s) acc += anb[s * mb::kStateC + c];
1084	        G.C_bias[c] += acc;
1085	    }
1086	    __syncthreads();
1087	    mb_rmsnorm_bwd_rawx(anb, &a->Cr[0][0], &a->Cr_r[0], L.C_norm_w,
1088	                        &sm->xproj[0][mb::kOffCr], G.C_norm_w, sm->red, mb::kStateC, mb::kXProj);
1089	    __syncthreads();
1090	    // --- C imag (dCi2 = -dCbar1, since Cbar imag = -Ci2) ---
1091	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kStateC; idx += blockDim.x) {
1092	        const int s = idx / mb::kStateC, c = idx % mb::kStateC;
1093	        anb[s * mb::kStateC + c] = -sm->dCbar[s][c][1];
1094	    }
1095	    __syncthreads();
1096	    for (int c = threadIdx.x; c < mb::kStateC; c += blockDim.x) {
1097	        float acc = 0.f; for (int s = 0; s < mb::kSeq; ++s) acc += anb[s * mb::kStateC + c];
1098	        G.Chat_bias[c] += acc;
1099	    }
1100	    __syncthreads();
1101	    mb_rmsnorm_bwd_rawx(anb, &a->Ci[0][0], &a->Ci_r[0], L.Chat_norm_w,
1102	                        &sm->xproj[0][mb::kOffCi], G.Chat_norm_w, sm->red, mb::kStateC, mb::kXProj);
1103	    __syncthreads();
1104	    // x_proj is now fully assembled in sm->xproj (dt_lr|A_mod|theta|u_lam|Br|Bi|Cr|Ci).
1105	    //   x_proj bwd: dW_xproj += xproj^T @ x_in ; dx_in(x_proj path) = xproj @ x_proj_w
1106	    //   -> ADD to dx_in accumulator (sm->adj_c).
1107	    mb_linear_bwd(&sm->xproj[0][0], mb::kXProj, &a->x_in[0][0], mb::kDInner, L.x_proj_w,
1108	                  mb::kDInner, mb::kXProj, G.x_proj_w, nullptr, &sm->adj_c[0][0], mb::kDInner, false);
1109	    // x_in fans into THREE: scan (in adj_c via dx_acc), x_proj (just added), D-skip
1110	    //   (the D-path: dy_skip*D was added to adj_c above). All folded into adj_c now.
1111	    //   dx_in = adj_c (complete). x_in = x_main (no SiLU) -> dx_main = dx_in.
1112	    // in_proj bwd: dxz = [dx_main | dz]. dx_main = adj_c (stride kDInner) ;
1113	    //   dz = sm->wff_b (stride kDff). Build the in_proj dW + dX directly:
1114	    //   dW_in += dxz^T @ xn ; dx = dxz @ in_w -> dxn.
1115	    {
1116	        const int half = mb::kDInner;
1117	        for (int o = threadIdx.x; o < 2 * mb::kDInner; o += blockDim.x) {
1118	            const bool lo = (o < half);
1119	            const float* dyo = lo ? &sm->adj_c[0][0] : &sm->wff_b[0][0];
1120	            const int dystride = lo ? mb::kDInner : mb::kDff;
1121	            const int oo = lo ? o : (o - half);
1122	            float* gw = G.in_w + (int64_t)o * mb::kD;
1123	            for (int i = 0; i < mb::kD; ++i) {
1124	                float acc = 0.0f;
1125	                #pragma unroll
1126	                for (int s = 0; s < mb::kSeq; ++s)
1127	                    acc += dyo[s * dystride + oo] * xn[s * mb::kD + i];
1128	                gw[i] += acc;
1129	            }
1130	        }
1131	        __syncthreads();
1132	        // dxn[s,i] = Σ_{o<di} dx_main[s,o]*in_w[o,i] + Σ_{o<di} dz[s,o]*in_w[di+o,i].
1133	        for (int idx = threadIdx.x; idx < mb::kSeq * mb::kD; idx += blockDim.x) {
1134	            const int s = idx / mb::kD, i = idx % mb::kD;
1135	            float acc = 0.0f;
1136	            for (int o = 0; o < mb::kDInner; ++o) {
1137	                acc += sm->adj_c[s][o] * L.in_w[(int64_t)o * mb::kD + i];
1138	                acc += sm->wff_b[s][o] * L.in_w[(int64_t)(mb::kDInner + o) * mb::kD + i];
1139	            }
1140	            dxn[s * mb::kD + i] = acc;
1141	        }
1142	        __syncthreads();
1143	    }
1144	}
1145	
1146	// ════════════════════════════════════════════════════════════════════════
1147	//  SwiGLU backward for one sample. Given dmlp_out [kSeq,d], accumulates gate/up/
1148	//  down weight grads into G and writes dh1n [kSeq,d] (grad wrt mlp_norm output).
1149	//  Mirrors mamba3_oracle.swiglu_backward. Scratch: wff_a/wff_b, adj_a (d-wide).
1150	// ════════════════════════════════════════════════════════════════════════
1151	__device__ inline void mb_swiglu_bwd(const MambaWeights::Layer& L, const MambaGrad::Layer& G,
1152	                             const float* __restrict__ h1n,  // [kSeq,d] (mlp_norm out, recomputed)
1153	                             MambaSampleSmem::LayerAct* a,
1154	                             const float* __restrict__ dmlp_out,  // [kSeq,d]
1155	                             float* __restrict__ dh1n,        // [kSeq,d] OUT
1156	                             MambaSampleSmem* sm) {
1157	    // recompute prod = silu(g_pre)*u -> sm->wff_a (down_proj input).
1158	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kDff; idx += blockDim.x) {
1159	        const int s = idx / mb::kDff, o = idx % mb::kDff;
1160	        sm->wff_a[s][o] = mb_silu(a->g_pre[s][o]) * a->u_mlp[s][o];
1161	    }
1162	    __syncthreads();
1163	    // down_proj bwd: dW_down += dmlp_out^T @ prod ; dprod = dmlp_out @ down_w -> wff_b.
1164	    mb_linear_bwd(dmlp_out, mb::kD, &sm->wff_a[0][0], mb::kDff, L.down_w,
1165	                  mb::kDff, mb::kD, G.down_w, nullptr, &sm->wff_b[0][0], mb::kDff, true);
1166	    // ds = dprod*u ; du = dprod*s ; dg_pre = ds*silu'(g_pre). Stage dg_pre -> wff_a,
1167	    //   du -> wff_b (dprod consumed in place).
1168	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kDff; idx += blockDim.x) {
1169	        const int s = idx / mb::kDff, o = idx % mb::kDff;
1170	        float dprod = sm->wff_b[s][o];
1171	        float sgp = mb_silu(a->g_pre[s][o]);
1172	        float ds = dprod * a->u_mlp[s][o];
1173	        float du = dprod * sgp;
1174	        sm->wff_a[s][o] = ds * mb_silu_grad(a->g_pre[s][o]);   // dg_pre
1175	        sm->wff_b[s][o] = du;                                  // du
1176	    }
1177	    __syncthreads();
1178	    // gate_proj bwd: dW_gate += dg_pre^T @ h1n ; dx_gate = dg_pre @ gate_w -> dh1n (SET).
1179	    mb_linear_bwd(&sm->wff_a[0][0], mb::kDff, h1n, mb::kD, L.gate_w,
1180	                  mb::kD, mb::kDff, G.gate_w, nullptr, dh1n, mb::kD, true);
1181	    // up_proj bwd: dW_up += du^T @ h1n ; dx_up = du @ up_w -> ADD to dh1n.
1182	    mb_linear_bwd(&sm->wff_b[0][0], mb::kDff, h1n, mb::kD, L.up_w,
1183	                  mb::kD, mb::kDff, G.up_w, nullptr, dh1n, mb::kD, false);
1184	}
1185	
1186	// ════════════════════════════════════════════════════════════════════════
1187	//  BACKWARD for one sample (CTA-cooperative). Assumes mb_forward_sample ran for
1188	//  THIS sample. Accumulates every weight grad into the CTA partial `g`. Mirrors
1189	//  mamba3_oracle.model_backward + block_backward.
1190	// ════════════════════════════════════════════════════════════════════════
1191	__device__ inline void mb_backward_sample(const MambaWeights& w, const MambaGrad& g,
1192	                                    const int* tokens_s, int target, int B,
1193	                                    MambaSampleSmem* sm) {
1194	    // ── CE bwd: dlogits = (softmax - onehot)/B. ──
1195	    float lmax = -CUDART_INF_F;
1196	    for (int o = threadIdx.x; o < mb::kPHead; o += blockDim.x) lmax = fmaxf(lmax, sm->logits[o]);
1197	    lmax = mb_block_max(lmax, sm->red);
1198	    float es = 0.0f;
1199	    for (int o = threadIdx.x; o < mb::kPHead; o += blockDim.x) es += __expf(sm->logits[o] - lmax);
1200	    es = mb_block_sum(es, sm->red);
1201	    float inv_es = 1.0f / es;
1202	    for (int o = threadIdx.x; o < mb::kPHead; o += blockDim.x) {
1203	        float smo = __expf(sm->logits[o] - lmax) * inv_es;
1204	        sm->logits[o] = (smo - ((o == target) ? 1.0f : 0.0f)) / (float)B;
1205	    }
1206	    __syncthreads();
1207	    // ── head: logits = hn @ out_w^T + out_b ; hn = fn_xhat[last]*norm_w (NO bias). ──
1208	    const float* xh = &sm->fn_xhat[mb::kSeq - 1][0];
1209	    for (int o = threadIdx.x; o < mb::kPHead; o += blockDim.x) {
1210	        float dl = sm->logits[o];
1211	        g.out_b[o] += dl;
1212	        float* gwrow = g.out_w + (int64_t)o * mb::kD;
1213	        #pragma unroll 4
1214	        for (int j = 0; j < mb::kD; ++j) gwrow[j] += dl * (xh[j] * w.norm_w[j]);
1215	    }
1216	    __syncthreads();
1217	    // dhn[j] = Σ_o dl[o]*out_w[o,j] -> sm->dr row 0.
1218	    for (int j = threadIdx.x; j < mb::kD; j += blockDim.x) {
1219	        float acc = 0.0f;
1220	        for (int o = 0; o < mb::kPHead; ++o) acc += sm->logits[o] * w.out_w[(int64_t)o * mb::kD + j];
1221	        sm->dr[0][j] = acc;
1222	    }
1223	    __syncthreads();
1224	    // ── final RMSNorm bwd (single row last): dw += dy*xhat ; dx -> dh[last]. ──
1225	    for (int j = threadIdx.x; j < mb::kD; j += blockDim.x) {
1226	        g.norm_w[j] += sm->dr[0][j] * xh[j];
1227	    }
1228	    __syncthreads();
1229	    {
1230	        float sdax = 0.0f;
1231	        for (int j = threadIdx.x; j < mb::kD; j += blockDim.x) {
1232	            float dxhat = sm->dr[0][j] * w.norm_w[j]; sdax += dxhat * xh[j];
1233	        }
1234	        sdax = mb_block_sum(sdax, sm->red);
1235	        float corr = sdax / (float)mb::kD;
1236	        float rs = sm->fn_r[mb::kSeq - 1];
1237	        for (int j = threadIdx.x; j < mb::kD; j += blockDim.x) {
1238	            float dxhat = sm->dr[0][j] * w.norm_w[j];
1239	            for (int s = 0; s < mb::kSeq; ++s) sm->dh[s][j] = 0.0f;
1240	            sm->dh[mb::kSeq - 1][j] = rs * (dxhat - xh[j] * corr);
1241	        }
1242	        __syncthreads();
1243	    }
1244	    // sm->dh = dL/d(final-block output) [kSeq,d], only last pos nonzero.
1245	
1246	    for (int li = mb::kLayers - 1; li >= 0; --li) {
1247	        const MambaWeights::Layer& L = w.layer[li];
1248	        const MambaGrad::Layer& G = g.layer[li];
1249	        MambaSampleSmem::LayerAct* a = &sm->act[li];
1250	        float* hin = &sm->layer_in[li][0][0];   // block input (raw x for mixer_norm bwd)
1251	        // h2 = h1 + mlp(mlp_norm(h1)). dh2 = sm->dh.
1252	        //   dh1 = dh2 (residual) + rmsnorm_bwd(swiglu_bwd(dh2)).
1253	        // recompute h1n = mlp_norm(h1) = (h1 * mlpn_r) * mlpn_w  (xhat from the raw h1).
1254	        for (int idx = threadIdx.x; idx < mb::kSeq * mb::kD; idx += blockDim.x) {
1255	            const int s = idx / mb::kD, j = idx % mb::kD;
1256	            sm->dr[s][j] = (a->h1[s][j] * a->mlpn_r[s]) * L.mlpn_w[j];   // h1n
1257	        }
1258	        __syncthreads();
1259	        // swiglu bwd: dmlp_out = dh2 (sm->dh) -> dh1n -> sm->fn_xhat (free: head done).
1260	        mb_swiglu_bwd(L, G, &sm->dr[0][0], a, &sm->dh[0][0], &sm->fn_xhat[0][0], sm);
1261	        // rmsnorm_mlp bwd (raw-x variant: recompute xhat from h1 * mlpn_r). dh1n in
1262	        //   sm->fn_xhat; out dh1_mlpnorm -> sm->dr (ldDx=kD).
1263	        mb_rmsnorm_bwd_rawx(&sm->fn_xhat[0][0], &a->h1[0][0], &a->mlpn_r[0], L.mlpn_w,
1264	                            &sm->dr[0][0], G.mlpn_w, sm->red, mb::kD, mb::kD);
1265	        for (int idx = threadIdx.x; idx < mb::kSeq * mb::kD; idx += blockDim.x) {
1266	            const int s = idx / mb::kD, j = idx % mb::kD;
1267	            sm->dh[s][j] += sm->dr[s][j];   // dh1 = dh2(residual) + mlp_norm path
1268	        }
1269	        __syncthreads();
1270	        // h1 = x + mixer(mixer_norm(x)). dh1 = sm->dh.
1271	        //   dx = dh1 (residual) + rmsnorm_bwd(mixer_bwd(dh1)).
1272	        // recompute xn = mixer_norm(hin) = (hin * mixn_r) * mixn_w (xhat from raw hin).
1273	        for (int idx = threadIdx.x; idx < mb::kSeq * mb::kD; idx += blockDim.x) {
1274	            const int s = idx / mb::kD, j = idx % mb::kD;
1275	            sm->dr[s][j] = (hin[s * mb::kD + j] * a->mixn_r[s]) * L.mixn_w[j];   // xn
1276	        }
1277	        __syncthreads();
1278	        // mixer bwd: dmix_out = dh1 (sm->dh) ; xn in sm->dr ; out dxn -> sm->fn_xhat.
1279	        mb_mixer_bwd(L, G, &sm->dr[0][0], a, &sm->dh[0][0], &sm->fn_xhat[0][0], sm);
1280	        // rmsnorm_mix bwd (raw-x variant: recompute xhat from hin * mixn_r).
1281	        mb_rmsnorm_bwd_rawx(&sm->fn_xhat[0][0], hin, &a->mixn_r[0], L.mixn_w,
1282	                            &sm->dr[0][0], G.mixn_w, sm->red, mb::kD, mb::kD);
1283	        for (int idx = threadIdx.x; idx < mb::kSeq * mb::kD; idx += blockDim.x) {
1284	            const int s = idx / mb::kD, j = idx % mb::kD;
1285	            sm->dh[s][j] += sm->dr[s][j];   // dx = dh1(residual) + mixer_norm path
1286	        }
1287	        __syncthreads();
1288	        // sm->dh now = grad wrt the previous block's output (or the embedding for li=0).
1289	    }
1290	
1291	    // ── embedding backward: dh = grad wrt h0 [kSeq,d]. ──
1292	    for (int j = threadIdx.x; j < mb::kD; j += blockDim.x) {
1293	        #pragma unroll
1294	        for (int s = 0; s < mb::kSeq; ++s) {
1295	            float d = sm->dh[s][j];
1296	            g.tok[(int64_t)tokens_s[s] * mb::kD + j] += d;
1297	            g.pos[(int64_t)s * mb::kD + j] += d;
1298	        }
1299	    }
1300	    __syncthreads();
1301	}
